const wfData = $getWorkflowStaticData('global');
const last = wfData.lastCreated || 0;
const body = $input.first().json;
const fresh = (body.products || [])
  .filter(p => (p.createdAt || 0) > last)
  .sort((a, b) => a.createdAt - b.createdAt);
if (fresh.length === 0) return { done: true, processed: 0 };
const product = fresh[0];
return {
  done: false,
  product,
  imageUrl: (product.images && product.images[0]) ? product.images[0] : '',
  nextLast: product.createdAt,
  pending: fresh.length
};

const item = $input.first();
const b64 = item.binary && item.binary.data ? item.binary.data : '';
return {
  product: $node['Filtrar nuevo'].json.product,
  body: {
    contents: [{
      parts: [
        { text: 'Sos director de arte senior de FLORES, e-commerce de calzado premium boliviano (estética editorial, carmín #9B1C1C, sharp, sin amarillo, mujer-first). Mirá la foto del producto y escribí EXACTAMENTE 3 prompts de poster promocional en español de Bolivia, listos para pegar en una IA generadora de imágenes. Formato: PROMPT 1 / PROMPT 2 / PROMPT 3. Cada prompt: tema editorial, pose/encuadre, fondo, luz, estilo. No inventes descuentos ni urgencia.' },
        { inlineData: { mimeType: 'image/jpeg', data: b64 } }
      ]
    }]
  }
};

const data = $input.first().json;
const text = (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) ? data.candidates[0].content.parts.map(x => x.text || '').join('\n') : JSON.stringify(data);
return { prompts: text };

const wfData = $getWorkflowStaticData('global');
const filter = $node['Filtrar nuevo'].json;
if (filter && !filter.done && filter.nextLast) {
  wfData.lastCreated = Math.max(wfData.lastCreated || 0, filter.nextLast);
}
return { watermark: wfData.lastCreated };
